class Solution {
    int getMaxConsecutive(vector<int>& bars) {
        sort(bars.begin(), bars.end());
        int best = 1, curr = 1;
        for (int i = 1; i < bars.size(); i++) {
            if (bars[i] == bars[i - 1] + 1) curr++;
            else curr = 1;
            best = max(best, curr);
        }
        return best;
    }
public:
    int maximizeSquareHoleArea(int n, int m, vector<int>& hBars, vector<int>& vBars) {
