        return side * side;
    }
};

class Solution {
    int getMaxConsecutive(int[] bars) {
        Arrays.sort(bars);
        int best = 1, curr = 1;
        for (int i = 1; i < bars.length; i++) {
            if (bars[i] == bars[i - 1] + 1) curr++;
            else curr = 1;
            best = Math.max(best, curr);
        }
        return best;
    }
    public int maximizeSquareHoleArea(int n, int m, int[] hBars, int[] vBars) {
        int side = Math.min(getMaxConsecutive(hBars) + 1, getMaxConsecutive(vBars) + 1);
        return side * side;
    }
}

/**
 * @param {number} n
 * @param {number} m
 * @param {number[]} hBars
 * @param {number[]} vBars
 * @return {number}
 */
var maximizeSquareHoleArea = function(n, m, hBars, vBars) {
    function getMaxConsecutive(bars) {
        bars.sort((a, b) => a - b);
        let best = 1, curr = 1;
        for (let i = 1; i < bars.length; i++) {
            if (bars[i] === bars[i - 1] + 1) curr++;
            else curr = 1;
            if (curr > best) best = curr;
        }
        return best;
    }
    const side = Math.min(getMaxConsecutive(hBars) + 1, getMaxConsecutive(vBars) + 1);
    return side * side;
};
